def valuation_closure(v, universe, s):
    if not s:
        sup_val = 0
    else:
        sup_val = max(v[x] for x in s)
    return frozenset(x for x in universe if v[x] <= sup_val)

def construct_realization(cl, universe):
    base = len(cl(frozenset()))
    return {x: len(cl(frozenset([x]))) - base for x in universe}

def normalize_valuation(v):
    keys = list(v.keys())
    return {x: sum(1 for y in keys if v[y] < v[x]) for x in keys}

def is_realizable(cl, universe):
    closed = [s for s in powerset(universe) if cl(s) == s]
    for i, s in enumerate(closed):
        for t in closed[i+1:]:
            if not (s <= t or t <= s):
                return False
    return True
